type Ledger struct {
	mu sync.Mutex
	m  map[string]int64
}

func (l *Ledger) Transfer(from, to string, cents int64) {
	l.mu.Lock()
	defer l.mu.Unlock()          // released on every return path
	l.m[from] -= cents
	l.m[to] += cents
}

